INSERT INTO `articles` (`id`, `html`, `text`, `delta`, `product_id`, `deleted`, `created_at`) VALUES
(40, '&lt;h2&gt;Why AX SERIES - AX32 Cable?&lt;/h2&gt;&lt;ul&gt;&lt;li&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);&quot;&gt;Ideal for individual, fleet and public use&lt;/span&gt;&lt;/li&gt;&lt;li&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);&quot;&gt;Optional wired/wireless connection for Central Management System&lt;/span&gt;&lt;/li&gt;&lt;li&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);&quot;&gt;Supports RFID card and QR code for user authentication&lt;/span&gt;&lt;/li&gt;&lt;li&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);&quot;&gt;Input: 200Vac~240Vac&lt;/span&gt;&lt;/li&gt;&lt;li&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);&quot;&gt;Modern, ergonomic and customizable design&lt;/span&gt;&lt;/li&gt;&lt;li&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);&quot;&gt;Optional 5 inch LCD screen&lt;/span&gt;&lt;/li&gt;&lt;li&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);&quot;&gt;IP56 protection level suitable for indoor/outdoor environments&lt;/span&gt;&lt;/li&gt;&lt;li&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);&quot;&gt;OTA software update support.&lt;/span&gt;&lt;/li&gt;&lt;li&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);&quot;&gt;Charging interface: IEC 62196-2 [Type-2]&lt;/span&gt;&lt;/li&gt;&lt;li&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);&quot;&gt;OCPP 1.6 Json supported (upgradeable to 2.0)&lt;/span&gt;&lt;/li&gt;&lt;li&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);&quot;&gt;ISO 15118 supported&lt;/span&gt;&lt;/li&gt;&lt;li&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);&quot;&gt;It provides suitable solutions for your electrical infrastructure by supporting load management.&lt;/span&gt;&lt;/li&gt;&lt;/ul&gt;', 'Why AX SERIES - AX32 Cable?\nIdeal for individual, fleet and public use\nOptional wired/wireless connection for Central Management System\nSupports RFID card and QR code for user authentication\nInput: 200Vac~240Vac\nModern, ergonomic and customizable design\nOptional 5 inch LCD screen\nIP56 protection level suitable for indoor/outdoor environments\nOTA software update support.\nCharging interface: IEC 62196-2 [Type-2]\nOCPP 1.6 Json supported (upgradeable to 2.0)\nISO 15118 supported\nIt provides suitable solutions for your electrical infrastructure by supporting load management.\n', '{\"ops\":[{\"insert\":\"Why AX SERIES - AX32 Cable?\"},{\"attributes\":{\"header\":2},\"insert\":\"\\n\"},{\"attributes\":{\"background\":\"#ffffff\",\"color\":\"#000000\"},\"insert\":\"Ideal for individual, fleet and public use\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"},{\"attributes\":{\"background\":\"#ffffff\",\"color\":\"#000000\"},\"insert\":\"Optional wired/wireless connection for Central Management System\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"},{\"attributes\":{\"background\":\"#ffffff\",\"color\":\"#000000\"},\"insert\":\"Supports RFID card and QR code for user authentication\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"},{\"attributes\":{\"background\":\"#ffffff\",\"color\":\"#000000\"},\"insert\":\"Input: 200Vac~240Vac\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"},{\"attributes\":{\"background\":\"#ffffff\",\"color\":\"#000000\"},\"insert\":\"Modern, ergonomic and customizable design\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"},{\"attributes\":{\"background\":\"#ffffff\",\"color\":\"#000000\"},\"insert\":\"Optional 5 inch LCD screen\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"},{\"attributes\":{\"background\":\"#ffffff\",\"color\":\"#000000\"},\"insert\":\"IP56 protection level suitable for indoor/outdoor environments\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"},{\"attributes\":{\"background\":\"#ffffff\",\"color\":\"#000000\"},\"insert\":\"OTA software update support.\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"},{\"attributes\":{\"background\":\"#ffffff\",\"color\":\"#000000\"},\"insert\":\"Charging interface: IEC 62196-2 [Type-2]\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"},{\"attributes\":{\"background\":\"#ffffff\",\"color\":\"#000000\"},\"insert\":\"OCPP 1.6 Json supported (upgradeable to 2.0)\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"},{\"attributes\":{\"background\":\"#ffffff\",\"color\":\"#000000\"},\"insert\":\"ISO 15118 supported\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"},{\"attributes\":{\"background\":\"#ffffff\",\"color\":\"#000000\"},\"insert\":\"It provides suitable solutions for your electrical infrastructure by supporting load management.\"},{\"attributes\":{\"list\":\"bullet\"},\"insert\":\"\\n\"}]}', 12, 0, '2024-10-13 11:07:23');
